<?php
declare(strict_types=1);
$config=require dirname(__DIR__).'/config/app.php';require dirname(__DIR__).'/app/Core/Security.php';require dirname(__DIR__).'/app/Core/Database.php';require dirname(__DIR__).'/app/Core/SchemaInspector.php';require dirname(__DIR__).'/app/Core/AuditLogger.php';require dirname(__DIR__).'/app/Core/WorkflowHelpers.php';require dirname(__DIR__).'/app/Services/Authorization.php';Security::startSession($config);
if(!Security::enforceAuthenticatedSession($config)){Security::destroySession();header('Location: login.php');exit;}
try{$db=Database::connection();$user=Authorization::user($db,(int)$_SESSION['user_id']);if(!$user){Security::destroySession();header('Location: login.php');exit;}if(!Authorization::can($db,$user,'content.manage')&&!Authorization::can($db,$user,'transparency.manage')){http_response_code(403);exit('Content management permission required.');}}
catch(Throwable $e){error_log('Content manager: '.$e->getMessage());http_response_code(503);exit('Content management is unavailable.');}
$message=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!Security::verifyCsrf($_POST['_csrf']??null)){http_response_code(419);$error='Session expired. Refresh and try again.';}
 else try{$action=(string)($_POST['action']??'');$db->beginTransaction();
  if($action==='create_content'){
   if(!Authorization::can($db,$user,'content.manage'))throw new InvalidArgumentException('Content creation permission required.');
   $type=(string)($_POST['content_type']??'');$types=['ARTICLE','ANNOUNCEMENT','NOTICE','ISSUANCE'];$title=WorkflowHelpers::clean((string)($_POST['title']??''),220);$summary=WorkflowHelpers::clean((string)($_POST['summary']??''),500);$body=WorkflowHelpers::clean((string)($_POST['body']??''),15000);$slug=strtolower(trim((string)($_POST['slug']??'')));$slug=preg_replace('/[^a-z0-9]+/','-',trim($slug,'-'));
   if(!in_array($type,$types,true)||$title===''||$body===''||$slug==='')throw new InvalidArgumentException('Complete the content type, title, URL slug, and body.');
   $q=$db->prepare("INSERT INTO content_items (content_type,slug,title,summary,body,status,created_by_user_id) VALUES (:type,:slug,:title,:summary,:body,'DRAFT',:uid)");$q->execute(['type'=>$type,'slug'=>$slug,'title'=>$title,'summary'=>$summary?:null,'body'=>$body,'uid'=>$user['user_id']]);$id=(int)$db->lastInsertId();$r=$db->prepare('INSERT INTO content_revisions (content_id,title,summary,body,changed_by_user_id,change_note) VALUES (:id,:title,:summary,:body,:uid,\'Initial draft\')');$r->execute(['id'=>$id,'title'=>$title,'summary'=>$summary?:null,'body'=>$body,'uid'=>$user['user_id']]);AuditLogger::record($db,(int)$user['user_id'],'CONTENT_DRAFT_CREATED','content_item',$id,['content_type'=>$type]);$message='Draft saved. An authorized administrator must publish it.';
  } elseif($action==='publish_content'||$action==='archive_content'){
   if($user['role_code']!=='BARANGAY_ADMINISTRATOR'||!Authorization::can($db,$user,'content.manage'))throw new InvalidArgumentException('Only an authorized Barangay Administrator may publish or archive content.');$id=(int)($_POST['id']??0);if($id<1)throw new InvalidArgumentException('Invalid content item.');$status=$action==='publish_content'?'PUBLISHED':'ARCHIVED';$q=$db->prepare('UPDATE content_items SET status=:status,approved_by_user_id=:uid,published_at=CASE WHEN :publish=1 THEN NOW() ELSE published_at END,updated_at=NOW() WHERE content_id=:id');$q->execute(['status'=>$status,'uid'=>$user['user_id'],'publish'=>$action==='publish_content'?1:0,'id'=>$id]);AuditLogger::record($db,(int)$user['user_id'],'CONTENT_'.$status,'content_item',$id);$message='Content status updated.';
  } elseif($action==='create_publication'){
   if(!Authorization::can($db,$user,'transparency.manage'))throw new InvalidArgumentException('Transparency management permission required.');$category=(string)($_POST['category']??'');$categories=['TRANSPARENCY_SEAL','BUDGET','PROCUREMENT','ANNUAL_REPORT','OPEN_DATA','LAW_OR_ISSUANCE','OTHER'];$title=WorkflowHelpers::clean((string)($_POST['title']??''),220);$description=WorkflowHelpers::clean((string)($_POST['description']??''),1000);$link=trim((string)($_POST['document_url']??''));$date=trim((string)($_POST['published_date']??''));if(!in_array($category,$categories,true)||$title==='')throw new InvalidArgumentException('Choose a valid category and title.');if($link!==''&&(!filter_var($link,FILTER_VALIDATE_URL)||parse_url($link,PHP_URL_SCHEME)!=='https'))throw new InvalidArgumentException('Public document links must use HTTPS.');if($date!==''&&!WorkflowHelpers::validDate($date))throw new InvalidArgumentException('Enter a valid publication date.');$q=$db->prepare("INSERT INTO public_documents (category,title,description,document_url,published_date,status,uploaded_by_user_id) VALUES (:category,:title,:description,:url,:date,'DRAFT',:uid)");$q->execute(['category'=>$category,'title'=>$title,'description'=>$description?:null,'url'=>$link?:null,'date'=>$date?:null,'uid'=>$user['user_id']]);$id=(int)$db->lastInsertId();AuditLogger::record($db,(int)$user['user_id'],'PUBLIC_DOCUMENT_DRAFT_CREATED','public_document',$id,['category'=>$category]);$message='Public document draft saved. An authorized administrator must publish it.';
  } elseif($action==='create_charter'){
   if(!Authorization::can($db,$user,'content.manage'))throw new InvalidArgumentException('Citizen Charter editing permission required.');
   $code=strtoupper(trim((string)($_POST['service_code']??'')));$name=WorkflowHelpers::clean((string)($_POST['service_name']??''),180);$desc=WorkflowHelpers::clean((string)($_POST['charter_description']??''),1000);$requirements=WorkflowHelpers::clean((string)($_POST['requirements_text']??''),5000);$fee=WorkflowHelpers::clean((string)($_POST['fee_text']??''),255);$time=WorkflowHelpers::clean((string)($_POST['processing_time_text']??''),255);$channel=WorkflowHelpers::clean((string)($_POST['service_channel']??''),255);
   if(!preg_match('/^[A-Z0-9_]{3,80}$/',$code)||$name===''||$requirements===''||$fee===''||$time==='')throw new InvalidArgumentException('Complete the service code, name, requirements, fee, and processing time.');
   $q=$db->prepare("INSERT INTO citizen_charter_services (service_code,service_name,description,requirements_text,fee_text,processing_time_text,service_channel,status) VALUES (:code,:name,:description,:requirements,:fee,:time,:channel,'DRAFT')");$q->execute(['code'=>$code,'name'=>$name,'description'=>$desc?:null,'requirements'=>$requirements,'fee'=>$fee,'time'=>$time,'channel'=>$channel?:null]);$id=(int)$db->lastInsertId();AuditLogger::record($db,(int)$user['user_id'],'CITIZEN_CHARTER_DRAFT_CREATED','citizen_charter_service',$id,['service_code'=>$code]);$message='Citizen Charter draft saved. An authorized administrator must publish it.';
  } elseif($action==='publish_charter'||$action==='archive_charter'){
   if($user['role_code']!=='BARANGAY_ADMINISTRATOR'||!Authorization::can($db,$user,'content.manage'))throw new InvalidArgumentException('Only an authorized Barangay Administrator may publish or archive Citizen Charter entries.');$id=(int)($_POST['id']??0);if($id<1)throw new InvalidArgumentException('Invalid Citizen Charter entry.');$status=$action==='publish_charter'?'PUBLISHED':'ARCHIVED';$q=$db->prepare('UPDATE citizen_charter_services SET status=:status,updated_at=NOW() WHERE charter_service_id=:id');$q->execute(['status'=>$status,'id'=>$id]);AuditLogger::record($db,(int)$user['user_id'],'CITIZEN_CHARTER_'.$status,'citizen_charter_service',$id);$message='Citizen Charter status updated.';
  } elseif($action==='publish_publication'||$action==='archive_publication'){
   if($user['role_code']!=='BARANGAY_ADMINISTRATOR'||!Authorization::can($db,$user,'transparency.manage'))throw new InvalidArgumentException('Only an authorized Barangay Administrator may publish or archive public documents.');$id=(int)($_POST['id']??0);if($id<1)throw new InvalidArgumentException('Invalid public document.');$status=$action==='publish_publication'?'PUBLISHED':'ARCHIVED';$q=$db->prepare('UPDATE public_documents SET status=:status,updated_at=NOW() WHERE public_document_id=:id');$q->execute(['status'=>$status,'id'=>$id]);AuditLogger::record($db,(int)$user['user_id'],'PUBLIC_DOCUMENT_'.$status,'public_document',$id);$message='Public document status updated.';
  } else throw new InvalidArgumentException('Unknown content action.');
  $db->commit();
 }catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Content action: '.$e->getMessage());$error='Unable to save this content item. Check that the URL slug is unique.';}
}
$items=$db->query('SELECT content_id,content_type,slug,title,status,created_at FROM content_items ORDER BY created_at DESC LIMIT 50')->fetchAll(PDO::FETCH_ASSOC);$docs=$db->query('SELECT public_document_id,category,title,status,published_date FROM public_documents ORDER BY created_at DESC LIMIT 50')->fetchAll(PDO::FETCH_ASSOC);$charters=$db->query('SELECT charter_service_id,service_code,service_name,status,fee_text,processing_time_text FROM citizen_charter_services ORDER BY service_name')->fetchAll(PDO::FETCH_ASSOC);
require dirname(__DIR__).'/app/Core/PublicPage.php';pageHeader('Content Management','Draft, review, and publish public portal content.');?>
<main id="main-content"><section class="page-hero"><div class="page-hero-inner"><p class="eyebrow">AUTHORIZED STAFF</p><h1>Content Management</h1><p>Draft public content and publish only after official review and approval.</p></div></section><section class="section"><div class="notice warning"><b>Publishing responsibility</b><p>Only publish verified information and documents approved for public release. Do not upload confidential, personal, or restricted records. File upload is not enabled in this demo; use a vetted HTTPS document link.</p></div><?php if($message): ?><div class="notice info" role="status"><?= Security::e($message) ?></div><?php endif; ?><?php if($error): ?><div class="notice warning" role="alert"><?= Security::e($error) ?></div><?php endif; ?>
<div class="content-layout"><article class="content-panel"><h2>Create an article or announcement draft</h2><form class="portal-form" method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="create_content"><label>Content type *<select name="content_type" required><option value="ARTICLE">Article</option><option value="ANNOUNCEMENT">Announcement</option><option value="NOTICE">Public Notice</option><option value="ISSUANCE">Law / Issuance</option></select></label><label>Title *<input name="title" maxlength="220" required></label><label>URL slug *<input name="slug" maxlength="180" pattern="[A-Za-z0-9-]+" required placeholder="community-cleanup-announcement"></label><label>Summary<input name="summary" maxlength="500"></label><label>Content *<textarea name="body" rows="8" maxlength="15000" required></textarea></label><button class="auth-submit" type="submit">Save draft</button></form></article><article class="content-panel"><h2>Add a transparency document draft</h2><form class="portal-form" method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="create_publication"><label>Category *<select name="category" required><option value="TRANSPARENCY_SEAL">Transparency Seal</option><option value="BUDGET">Budget</option><option value="PROCUREMENT">Procurement &amp; Bidding</option><option value="ANNUAL_REPORT">Annual Report</option><option value="OPEN_DATA">Open Data</option><option value="LAW_OR_ISSUANCE">Law / Issuance</option><option value="OTHER">Other</option></select></label><label>Title *<input name="title" maxlength="220" required></label><label>Description<textarea name="description" rows="3" maxlength="1000"></textarea></label><label>HTTPS document URL<input type="url" name="document_url" placeholder="https://..." maxlength="1000"></label><label>Publication date<input type="date" name="published_date"></label><button class="auth-submit" type="submit">Save document draft</button></form></article><article class="content-panel"><h2>Create a Citizen’s Charter draft</h2><form class="portal-form" method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="action" value="create_charter"><label>Service code *<input name="service_code" maxlength="80" pattern="[A-Za-z0-9_]+" required></label><label>Service name *<input name="service_name" maxlength="180" required></label><label>Description<textarea name="charter_description" rows="2" maxlength="1000"></textarea></label><label>Requirements *<textarea name="requirements_text" rows="3" maxlength="5000" required></textarea></label><label>Fees *<input name="fee_text" maxlength="255" required></label><label>Processing time *<input name="processing_time_text" maxlength="255" required></label><label>Service channel<input name="service_channel" maxlength="255"></label><button class="auth-submit" type="submit">Save Charter draft</button></form></article></div>
<section class="workflow-section"><h2>Content items</h2><?php if(!$items): ?><p>No content drafts or published items yet.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Type</th><th>Title</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($items as $r): ?><tr><td><?= Security::e($r['content_type']) ?></td><td><?= Security::e($r['title']) ?></td><td><?= Security::e($r['status']) ?></td><td><?= Security::e($r['created_at']) ?></td><td><?php if($user['role_code']==='BARANGAY_ADMINISTRATOR'&&$r['status']!=='PUBLISHED'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="id" value="<?= (int)$r['content_id'] ?>"><button name="action" value="publish_content" type="submit">Publish</button><button name="action" value="archive_content" type="submit">Archive</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="workflow-section"><h2>Transparency documents</h2><?php if(!$docs): ?><p>No transparency document drafts yet.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Category</th><th>Title</th><th>Status</th><th>Publication date</th><th>Action</th></tr></thead><tbody><?php foreach($docs as $r): ?><tr><td><?= Security::e($r['category']) ?></td><td><?= Security::e($r['title']) ?></td><td><?= Security::e($r['status']) ?></td><td><?= Security::e($r['published_date']??'—') ?></td><td><?php if($user['role_code']==='BARANGAY_ADMINISTRATOR'&&$r['status']!=='PUBLISHED'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="id" value="<?= (int)$r['public_document_id'] ?>"><button name="action" value="publish_publication" type="submit">Publish</button><button name="action" value="archive_publication" type="submit">Archive</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<section class="workflow-section"><h2>Citizen’s Charter entries</h2><?php if(!$charters): ?><p>No Citizen’s Charter entries yet.</p><?php else: ?><div class="table-wrap"><table class="data-table"><thead><tr><th>Code</th><th>Service</th><th>Fees</th><th>Processing time</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($charters as $r): ?><tr><td><?= Security::e($r['service_code']) ?></td><td><?= Security::e($r['service_name']) ?></td><td><?= Security::e($r['fee_text']) ?></td><td><?= Security::e($r['processing_time_text']) ?></td><td><?= Security::e($r['status']) ?></td><td><?php if($user['role_code']==='BARANGAY_ADMINISTRATOR'&&$r['status']!=='PUBLISHED'): ?><form method="post"><input type="hidden" name="_csrf" value="<?= Security::e(Security::csrfToken()) ?>"><input type="hidden" name="id" value="<?= (int)$r['charter_service_id'] ?>"><button name="action" value="publish_charter" type="submit">Publish</button><button name="action" value="archive_charter" type="submit">Archive</button></form><?php else: ?>—<?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section></section></main><?php pageFooter();
